<script setup>
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ArrowLeft, Printer, RefreshCw, CreditCard } from 'lucide-vue-next';
import WorkspaceShell from '@/Layouts/WorkspaceShell.vue';
import Button from '@/Components/UI/Button.vue';
defineProps({ organization: Object, order: Object });
const action = useForm({});
const money = (value, currency) => `${currency} ${Number(value).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const print = () => window.print();
</script>
<template>
    <Head title="Company order" />
    <WorkspaceShell workspace="organization"><div class="mx-auto max-w-4xl space-y-6 company-billing">
        <Link href="/organization/billing" class="inline-flex items-center gap-2 text-sm text-surface-500 print:hidden"><ArrowLeft class="h-4 w-4" /> Company billing</Link>
        <header class="flex flex-wrap items-center justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-widest text-primary-700">JK Michaels · {{ organization.name }}</p><h1 class="mt-2 text-3xl font-display font-bold">{{ order.status === 'paid' ? 'Payment receipt' : 'Company order' }}</h1></div><Button variant="secondary" class="print:hidden" @click="print"><Printer class="h-4 w-4" /> Print / save PDF</Button></header>
        <p v-if="order.billing_details?.payment_mode === 'test'" role="status" class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm font-semibold text-amber-900">TEST PAYMENT — This order uses sandbox payments. It is not evidence of a live financial transaction.</p>
        <section class="rounded-2xl border border-surface-200 bg-white p-6 sm:p-8"><div class="grid gap-6 sm:grid-cols-2"><div><h2 class="text-xs font-semibold uppercase tracking-widest text-surface-500">Billed to</h2><p class="mt-3 font-semibold">{{ order.billing_details?.name }}</p><p class="mt-1 text-sm text-surface-600">{{ order.billing_details?.contact_email }}</p><p class="mt-1 whitespace-pre-line text-sm text-surface-600">{{ order.billing_details?.address }}</p><p class="mt-1 text-sm text-surface-600">{{ order.billing_details?.country }}</p></div><div><h2 class="text-xs font-semibold uppercase tracking-widest text-surface-500">Order details</h2><p class="mt-3 break-all text-sm font-semibold">{{ order.uuid }}</p><p class="mt-2 text-sm text-surface-500">Created: {{ order.created_at }}</p><p v-if="order.paid_at" class="mt-1 text-sm text-surface-500">Verified payment: {{ order.paid_at }}</p><p class="mt-3 text-sm font-semibold capitalize">Status: {{ order.status }}</p></div></div>
            <div class="mt-8 overflow-x-auto"><table class="w-full text-left text-sm"><caption class="sr-only">Company course purchase details</caption><thead class="border-b border-surface-200 text-surface-500"><tr><th scope="col" class="py-3 pr-4">Course</th><th scope="col" class="px-3 py-3 text-right">Places</th><th scope="col" class="px-3 py-3 text-right">Per place</th><th scope="col" class="py-3 pl-3 text-right">Total</th></tr></thead><tbody><tr v-for="(item, index) in order.items" :key="index" class="border-b border-surface-100"><td class="py-4 pr-4 font-medium">{{ item.name }}</td><td class="px-3 py-4 text-right">{{ item.quantity }}</td><td class="whitespace-nowrap px-3 py-4 text-right">{{ money(item.unit_price, order.currency) }}</td><td class="whitespace-nowrap py-4 pl-3 text-right">{{ money(item.total_price, order.currency) }}</td></tr></tbody></table></div>
            <dl class="ml-auto mt-6 max-w-sm space-y-3 text-sm"><div class="flex justify-between gap-3"><dt class="text-surface-500">Subtotal</dt><dd>{{ money(order.subtotal, order.currency) }}</dd></div><div class="flex justify-between gap-3"><dt class="text-surface-500">Discount</dt><dd>−{{ money(order.discount_amount, order.currency) }}</dd></div><div class="flex justify-between gap-3 border-t border-surface-200 pt-4 text-lg font-bold"><dt>Total</dt><dd>{{ money(order.total, order.currency) }}</dd></div></dl>
            <div v-for="(payment, index) in order.payments" :key="index" class="mt-6 rounded-xl bg-surface-50 p-4 text-xs text-surface-600"><p class="font-semibold capitalize">{{ payment.gateway }} · {{ payment.status }}</p><p class="mt-1 break-all">Payment reference: {{ payment.gateway_reference }}</p></div>
        </section>
        <section v-if="order.status === 'pending'" class="rounded-2xl border border-primary-100 bg-primary-50 p-5 print:hidden"><h2 class="font-semibold text-primary-900">Finish your company purchase</h2><p class="mt-2 text-sm leading-relaxed text-primary-900">If you already paid, check payment status first. Your existing order and reference are retained. Places become available only after payment is verified.</p><div class="mt-4 flex flex-wrap gap-3"><Button v-if="order.payments.some(p => p.gateway === 'paystack' && p.status === 'pending')" variant="secondary" :loading="action.processing" @click="action.post(`/orders/${order.uuid}/refresh`, { preserveScroll: true })"><RefreshCw class="h-4 w-4" /> Check payment status</Button><Button :loading="action.processing" @click="action.post(`/orders/${order.uuid}/resume`, { preserveScroll: true })"><CreditCard class="h-4 w-4" /> Resume payment</Button></div><p v-for="(error, field) in action.errors" :key="field" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p></section>
        <p v-else-if="order.status === 'refunded'" class="rounded-xl bg-amber-50 p-4 text-sm text-amber-900">Payment has been refunded. Course access provided by this order is no longer available; learning records are preserved.</p>
        <Link v-if="order.status === 'paid'" href="/organization/courses" class="inline-flex rounded-xl bg-primary-600 px-5 py-3 text-sm font-semibold text-white print:hidden">Assign your course places →</Link>
    </div></WorkspaceShell>
</template>
<style>
@media print { body * { visibility: hidden; } .company-billing, .company-billing * { visibility: visible; } .company-billing { position: absolute; left: 0; top: 0; width: 100%; max-width: none; } }
</style>
